<script>
 import RegionState from './RegionState.svelte';import {createConfiguration} from '../lib/configuration.svelte';
 import TaskOutputActions from './TaskOutputActions.svelte';import {stopTask} from '../services/task-monitor.js';import {navigate} from '../app/shell.svelte';
 import {getAssistantApi,executeLocalPlan,executePipeline} from '../services/assistant.js';import {selection} from '../stores/selection.svelte';import {tasks} from '../stores/tasks.svelte';
 import {saveFile,descriptor} from '../local-downloads.js';
 import {onMount} from 'svelte';import {assistantPresets} from '../assistant-presets';import {Plus,X,ChevronUp,ChevronDown,Play,FolderOpen,ArrowUpRight,Check,RefreshCw,Square,Sparkles} from 'lucide-svelte';import {studio,current,run,goSettings,importImages,liveAssets} from '../studio.svelte';import {clone,rgb,hex,isTeam} from '../api';import {money} from '../cost';
 let instruction=$state(''),plan=$state({summary:"本地处理",steps:[],warnings:[],clarification:null,output:null}),presetName=$state(''),presets=$state([]),op=$state('adjust'),usage=$state(null);
 const assistantApi=getAssistantApi(),configuration=createConfiguration(()=>assistantApi.configured());const configured=$derived(configuration.state.configured);let localSubmitting=$state(false),localPlanning=$state(false),localTaskId=$state(null),localStatus=$state(''),localError=$state(''),presetStatus=$state(''),presetLoading=$state(false),presetError=$state('');const localBusy=$derived(localSubmitting||localTaskId&&['queued','running','waiting'].includes(tasks.byId[localTaskId]?.state));const localContext=$derived(selection.context||selection.snapshot());const unifiedTasks=$derived(Object.values(tasks.byId).filter(task=>task.projectId===studio.pid&&task.type!=='hybrid'));const legacyJobs=$derived(studio.jobs.filter(job=>!tasks.byId[job.id]?.pipeline));
 let execution=$state('realtime'),generationModel=$state(''),autoSubmitting=$state(false),autoTaskId=$state(null),autoStatus=$state(''),autoError=$state('');const autoBusy=$derived(autoSubmitting||autoTaskId&&['queued','running','waiting','submitted','cancelling'].includes(tasks.byId[autoTaskId]?.state));
 function chooseImage(id){studio.batchScope='selection';studio.selected=studio.selected.includes(id)?studio.selected.filter(x=>x!==id):[...studio.selected,id];}
 const stageName=s=>({queued:'等待处理',preparing:'正在准备图片',waiting:'等待供应商生成',submitting:'正在提交',attention:'需要检查',completed:'已完成',partial:'部分完成',pending:'等待处理',ready:'预处理完成',submitted:'已提交，等待生成',generating:'正在生成',uncertain:'结果待确认，请勿重复提交',generated:'图片已生成',done:'已保存',failed:'失败',cancelled:'已取消'}[s]||s);
 const stageValue=s=>({pending:0,ready:2,generated:4,done:5,failed:0,cancelled:0}[s]);
 function usePreset(p){instruction=p.instruction;}
 const templates={adjust:{op:'adjust',exposure:0,contrast:1,saturation:1,temperature:0},rotate:{op:'rotate',degrees:90},flip:{op:'flip',axis:'horizontal'},crop:{op:'crop',x:0,y:0,width:1,height:1},resize:{op:'resize',width:1000,height:1000,fit:'pad',background:[255,255,255]},flatten:{op:'flatten',background:[255,255,255]},blur:{op:'blur',sigma:1},sharpen:{op:'sharpen',sigma:1,threshold:3},denoise:{op:'denoise',strength:3},auto_center:{op:'auto_center',padding:.08},deskew:{op:'deskew',max_degrees:10}};
 const labels={width:'宽度',height:'高度',exposure:'曝光',contrast:'对比度',saturation:'饱和度',temperature:'色温',background:'背景颜色',padding:'边距比例',sigma:'强度',threshold:'阈值',strength:'强度',degrees:'角度',axis:'方向',fit:'适配方式',x:'横向起点',y:'纵向起点',adjust:"调色",rotate:"旋转",flip:"翻转",crop:"裁切",resize:"调整尺寸与补边",flatten:"填充透明背景",blur:"模糊",sharpen:"锐化",denoise:"降噪",auto_center:"主体居中",deskew:"纠正倾斜",max_degrees:"最大校正角度",maxBytes:"最大字节数"};
 $effect(()=>{if(studio.mode==='assistant')void configuration.load('deepseek');return()=>configuration.cancel();});
 onMount(()=>{void loadPresets();void refreshLegacyJobs();const timer=setInterval(()=>{void refreshLegacyJobs();},5000);return()=>clearInterval(timer);});
 async function refreshLegacyJobs(){try{const value=await assistantApi.legacyJobs();studio.jobs=value.jobs;studio.notices=value.notices;}catch(error){autoError=error.message;}}
 async function submitNatural(){if(autoBusy||!instruction.trim())return;const context=selection.snapshot();if(!context.resolvedTarget.ids.length){autoError='请先选择图片。';return;}autoSubmitting=true;autoError='';try{const result=await executePipeline(instruction,{execution,model:generationModel||null},context);autoTaskId=result?.task?.id||null;autoStatus=result?.confirmation?'进度、确认操作和结果会在右侧对话的同一执行行更新。':result?.task?'已提交，处理进度与结果位于右侧对话':'请查看右侧对话中的处理说明';}catch(error){autoError=error.message;}finally{autoSubmitting=false;}}
 async function parse(){localPlanning=true;localError='';const context=selection.snapshot(),request=instruction,prior=JSON.stringify(plan);try{const result=await assistantApi.plan(studio.pid,context,request);if(request!==instruction||JSON.stringify(selection.snapshot())!==JSON.stringify(context)||JSON.stringify(plan)!==prior)throw Error('要求、对象或步骤已更改，请重新生成方案。');plan=result.plan;usage=result;}catch(error){localError=error.message;}finally{localPlanning=false;}}
 async function apply(){if(localBusy||plan.clarification||!plan.steps.length&&!plan.output)return;const context=selection.snapshot();if(!context.resolvedTarget.ids.length){localError='请先选择图片。';return;}localSubmitting=true;localError='';try{const result=await executeLocalPlan(clone(plan),context);localTaskId=result?.task?.id||null;localStatus=result?.confirmation?'进度、确认操作和结果会在右侧对话的同一执行行更新。':result?.task?'已提交，结果和撤销位于右侧对话':'请查看对话中的提示';}catch(error){localError=error.message;}finally{localSubmitting=false;}}
 async function loadPresets(){presetLoading=true;presetError='';try{const value=await assistantApi.presets();presets=Object.entries(value).map(([name,plan])=>({name,plan}));}catch(error){presetError=error.message;}finally{presetLoading=false;}}
 async function savePreset(){presetStatus='保存中…';try{await assistantApi.savePreset(presetName,clone(plan));presets=Object.entries(await assistantApi.presets()).map(([name,plan])=>({name,plan}));presetStatus='已保存';}catch(error){presetStatus=error.message;}}
 function move(i,d){const j=i+d;if(j<0||j>=plan.steps.length)return;[plan.steps[i],plan.steps[j]]=[plan.steps[j],plan.steps[i]];}
</script>
<div class="workflow-panel assistant-panel" inert={!!studio.busy}><div class="workflow-heading"><h1>处理图片</h1><span>{localContext.resolvedTarget.ids.length} 张图片</span></div><div class="assistant-tabs segmented"><button class:active={studio.processTab==='auto'} onclick={()=>studio.processTab='auto'}>自然语言处理</button><button class:active={studio.processTab==='local'} onclick={()=>studio.processTab='local'}>本地处理步骤</button><button class:active={studio.processTab==='jobs'} onclick={()=>studio.processTab='jobs'}>任务列表 <span>{legacyJobs.length+unifiedTasks.length}</span></button></div>
{#if studio.processTab!=='jobs'}<p class="local-target">处理对象：{localContext.resolvedTarget.source==='mention'?'@引用':localContext.resolvedTarget.source==='selected'?'已选':localContext.resolvedTarget.source==='editor'?'当前图':'筛选结果'} {localContext.resolvedTarget.ids.length} 张</p><details><summary>选择处理图片 · 已选 {studio.selected.length} 张</summary><div class="button-row"><button class="line-button" onclick={()=>{studio.batchScope='selection';studio.selected=liveAssets().map(a=>a.id);}}>全选</button><button class="line-button" onclick={()=>{studio.batchScope='selection';studio.selected=[];}}>取消全选</button></div><div class="process-selection">{#each liveAssets() as a}<button class:selected={studio.selected.includes(a.id)} aria-pressed={studio.selected.includes(a.id)} onclick={()=>chooseImage(a.id)}><img src={studio.thumbs[a.id]} alt=""/><span>{a.name}</span></button>{/each}</div></details>{/if}
{#if !localContext.resolvedTarget.ids.length&&studio.processTab!=='jobs'}<div class="empty"><h2>请选择要处理的图片</h2><div class="button-row"><button class="primary" onclick={()=>importImages(false)}>导入图片</button><button class="line-button" onclick={()=>{studio.mode='edit';studio.view='grid';}}>打开图片列表</button></div></div>{:else if studio.processTab==='auto'}<div class="assistant-auto">{#if configuration.state.status==='idle'||configuration.state.status==='loading'}<RegionState compact state="loading" title="正在读取处理配置"/>{:else if configuration.state.status==='error'}<RegionState compact state="error" title="无法读取处理配置" message={configuration.state.error} onretry={()=>configuration.load('deepseek')}/>{:else if !configured&&assistantApi.mode!=='mock'}<RegionState compact state="empty" title="尚未配置 DeepSeek API"/>{/if}<h2>你想如何处理图片？</h2><p class="hint">输入要求后直接开始，原图保留，结果可撤销。只有数量、费用或配额达到门槛时在对话内确认。</p>{#if assistantApi.mode==='mock'}<p class="hint">模拟模式，不调用模型或返回假成图。</p>{/if}<div class="field-grid"><label>生成方式<select aria-label="混合生成方式" bind:value={execution}><option value="realtime">实时生成</option><option value="batch">异步 Batch</option></select></label><label>生图模型<select aria-label="混合生图模型" bind:value={generationModel}><option value="">自动选择</option>{#each studio.catalog?.models||[] as model}<option value={model.id}>{model.name}</option>{/each}</select></label></div>{#if generationModel.startsWith('GPT-Image')}<p class="hint">Poe 使用队列逐张生成，不调用 Google Batch。</p>{/if}<div class="assistant-presets" aria-label="常用指令">{#each assistantPresets as preset}<button class:active={instruction===preset.instruction} onclick={()=>usePreset(preset)}><b>{preset.name}</b><span>{preset.detail}</span></button>{/each}</div><textarea aria-label="处理要求" bind:value={instruction} rows="5" placeholder="产品主图，800*800，100kb"></textarea><div class="assistant-start"><span class="hint">结果自动写回已授权文件夹；未授权时可下载。</span><button class="primary" disabled={autoBusy||!instruction.trim()||!localContext.resolvedTarget.ids.length||!configured&&assistantApi.mode!=='mock'} onclick={submitNatural}><Sparkles size={15}/>{autoBusy?'处理中…':'开始处理'}</button></div><p class="hint" role="status">{autoStatus}</p>{#if autoError}<p class="inline-error" role="alert">{autoError}</p><button class="line-button" onclick={submitNatural}>重试</button>{/if}{#if configuration.state.status==='ready'&&!configured&&assistantApi.mode!=='mock'}{#if isTeam}<p class="hint">请联系主机管理员配置 DeepSeek API。</p>{:else}<button class="text-button" onclick={()=>goSettings('assistant')}>前往设置配置 DeepSeek API<ArrowUpRight size={13}/></button>{/if}{/if}</div>
{:else if studio.processTab==='local'}<div class="local-layout"><div class="local-plan"><div class="instruction-row"><textarea aria-label="本地处理要求" bind:value={instruction} placeholder="输入处理要求，或在下方添加步骤。" rows="2"></textarea><button class="line-button" disabled={!configured||!instruction.trim()||localPlanning||localBusy} onclick={parse}>生成方案</button></div>{#if usage}<span class="hint">{usage.usage?.total_tokens!=null?usage.usage.total_tokens+' 用量单位':'模型未返回用量'}{usage.cost?` · $${usage.cost.minimumUsd.toFixed(6)}–$${usage.cost.maximumUsd.toFixed(6)}`:''}</span>{/if}<div class="step-add"><select bind:value={op} aria-label="选择操作">{#each Object.keys(templates) as key}<option value={key}>{labels[key]}</option>{/each}</select><button class="line-button" onclick={()=>plan.steps.push(clone(templates[op]))} disabled={plan.steps.length>=20}><Plus size={14}/>添加步骤</button></div><div class="steps">{#each plan.steps as step,i}<div class="step"><div class="step-heading"><b>{i+1}. {labels[step.op]||step.op}</b><div><button aria-label={`Move step ${i+1} up`} disabled={i===0} onclick={()=>move(i,-1)}><ChevronUp size={14}/></button><button aria-label={`Move step ${i+1} down`} disabled={i===plan.steps.length-1} onclick={()=>move(i,1)}><ChevronDown size={14}/></button><button aria-label={`Remove step ${i+1}`} onclick={()=>plan.steps.splice(i,1)}><X size={14}/></button></div></div><div class="field-grid">{#each Object.entries(step).filter(([k])=>k!=='op') as [key,value]}<label>{labels[key]||key.replaceAll('_',' ')}{#if Array.isArray(value)}<input aria-label={`${step.op} ${key}`} type="color" value={hex(value)} onchange={e=>step[key]=rgb(e.target.value)}/>{:else if typeof value==='number'}<input aria-label={`${step.op} ${key}`} type="number" step={['width','height','threshold','degrees'].includes(key)?1:.05} value={value} onchange={e=>step[key]=Number(e.target.value)}/>{:else}<select aria-label={`${step.op} ${key}`} value={value} onchange={e=>step[key]=e.target.value}>{#each key==='axis'?['horizontal','vertical']:['pad','crop'] as option}<option value={option}>{{horizontal:'水平',vertical:'垂直',pad:'补边',crop:'裁切'}[option]||option}</option>{/each}</select>{/if}</label>{/each}</div></div>{/each}</div><label class="checkbox-label"><input type="checkbox" checked={!!plan.output} onchange={e=>plan.output=e.target.checked?{format:'webp',width:1000,height:1000,fit:'pad',maxBytes:500000,background:[255,255,255]}:null}/>自定义结果格式与尺寸</label>{#if plan.output}<div class="field-grid"><label>图片格式<select bind:value={plan.output.format}><option>webp</option><option>png</option><option>jpeg</option></select></label><label>画面适配方式<select bind:value={plan.output.fit}><option value="pad">补边</option><option value="crop">裁切</option></select></label>{#each ['width','height','maxBytes'] as key}<label>{labels[key]||key}<input type="number" min={key==='maxBytes'?0:1} bind:value={plan.output[key]}/></label>{/each}<label>背景颜色<input type="color" value={hex(plan.output.background)} onchange={e=>plan.output.background=rgb(e.target.value)}/></label></div>{/if}{#if plan.clarification}<p class="inline-error">{plan.clarification}</p>{/if}{#each plan.warnings||[] as warning}<p class="hint">{warning}</p>{/each}<div class="preset-save"><input aria-label="预设名称" placeholder="预设名称" bind:value={presetName}/><button class="line-button" disabled={!presetName.trim()||!!studio.busy} onclick={savePreset}>保存预设</button></div><p class="hint" role="status">{presetStatus}</p>{#if presetLoading}<RegionState compact state="loading" title="正在读取本地预设"/>{:else if presetError}<RegionState compact state="error" title="无法读取本地预设" message={presetError} onretry={loadPresets}/>{:else if !presets.length}<p class="hint">尚无本地预设，可保存当前步骤以便复用。</p>{/if}{#if presets.length}<select aria-label="选择本地预设" onchange={e=>{if(e.target.value==='')return;const p=presets[Number(e.target.value)];if(p)plan=clone(p.plan);}}><option value="">选择预设</option>{#each presets as p,i}<option value={i}>{p.name}</option>{/each}</select>{/if}</div><aside class="local-execution"><h3>直接执行</h3><p>按当前步骤处理 {localContext.resolvedTarget.ids.length} 张。原图保留，每张生成一个新版本，可在对话中撤销。</p>{#if plan.output}<p>同时导出 {plan.output.width} × {plan.output.height} 的 {plan.output.format.toUpperCase()}，结果自动写入已授权的项目文件夹；未授权时可下载。</p>{:else}<p>结果默认使用当前处理尺寸和WebP格式，自动写回已授权文件夹；未授权时可下载。</p>{/if}<button class="primary" disabled={localBusy||localPlanning||!localContext.resolvedTarget.ids.length||!plan.steps.length&&!plan.output||!!plan.clarification} onclick={apply}><Play size={14}/>{localBusy?'处理中…':'执行本地步骤'}</button><p class="hint" role="status">{localStatus}</p>{#if localError}<p class="inline-error" role="alert">{localError}</p><button class="line-button" onclick={()=>localError=''}>关闭提示</button>{/if}</aside></div>

{:else}<div class="task-list"><div class="section-row"><h3>后台任务</h3><button aria-label="刷新任务" onclick={refreshLegacyJobs}><RefreshCw size={15}/></button></div>{#each unifiedTasks as task (task.id)}<article class="task"><div class="task-heading"><b>{task.summary||'图片处理'}</b><span>{stageName(task.state)||task.state}</span></div><p>{task.done||0} / {task.total||task.targetCount||0} 张</p>{#each task.failures||[] as failure}<p class="inline-error">{failure.message}</p>{/each}{#each task.warnings||[] as warning}<p class="hint">{warning}</p>{/each}<div class="button-row">{#if !['done','partial','failed','cancelled'].includes(task.state)}<button class="line-button" onclick={()=>stopTask(task).catch(error=>studio.error=error.message)}>停止</button>{/if}{#if task.resultAssetIds?.length}<button class="line-button" onclick={()=>{studio.selected=[...task.resultAssetIds];navigate('/library');}}>在素材库中查看</button>{/if}</div><TaskOutputActions {task}/></article>{/each}{#each legacyJobs as job}<article class="task"><div class="task-heading"><b>{job.recipe.summary}</b><span class={`job-state ${job.state}`}>{stageName(job.state)}</span></div><p>{job.instruction}</p><div class="task-details"><span>{job.items.filter(i=>i.stage==='done').length} / {job.items.length} 张图片</span><span>{job.estimatedUsd!=null?money(job.estimatedUsd,studio.currency,studio.exchangeRate):''}</span></div>{#if job.error}<p class="inline-error">{job.error}</p>{/if}<details open><summary>逐图进度</summary>{#each job.items as item}<div class="task-item"><span>{item.name}</span><div class="item-progress"><span>{item.retentionStatus==='saved_locally'?'已保存到本机，主机副本已清理':item.retentionStatus==='expired'?'保留期已结束，主机副本已清理':stageName(item.stage)}</span><progress max="5" value={stageValue(item.stage)} aria-label={`${item.name}：${stageName(item.stage)}`}></progress>{#if item.exported&&isTeam}<a href={item.exported} download onclick={e=>{e.preventDefault();saveFile(descriptor(item.exported)).catch(e=>studio.error=e.message);}}>下载图片</a>{/if}</div>{#if item.error}<small>{item.error}</small>{/if}{#each item.warnings||[] as w}<small>{w}</small>{/each}</div>{/each}</details><div class="button-row"><button class="line-button" disabled={!job.items.some(i=>i.exported)} onclick={()=>run("正在打开结果",()=>assistantApi.openLegacy(job.id))}><FolderOpen size={14}/>{isTeam?"下载文件":"打开结果文件夹"}</button>{#if !['completed','partial','failed','cancelled'].includes(job.state)}<button class="text-button" onclick={()=>run("正在取消",async()=>{await assistantApi.cancelLegacy(job.id);await refreshLegacyJobs();})}><Square size={12}/>取消</button>{/if}{#if studio.notices.some(n=>n.id===job.id)}<button class="text-button" title="关闭此任务的完成提醒，不删除图片" onclick={()=>run('关闭提醒',async()=>{await assistantApi.ackLegacy(job.id);await refreshLegacyJobs();})}>关闭完成提醒</button>{/if}</div></article>{/each}{#if !legacyJobs.length&&!unifiedTasks.length}<div class="empty small"><h2>暂无后台任务</h2></div>{/if}</div>{/if}</div>


<style>.local-target{font-size:13px;line-height:1.7;margin-bottom:12px}.local-execution{padding:24px;border:1px solid var(--border);align-self:start;font-size:13px;line-height:1.7}.local-execution h3{font-size:14px;margin-bottom:12px}.local-execution p{margin:12px 0}.local-execution button{margin:12px 0}.local-execution [role=alert]{color:var(--danger)}</style>
